"""Mesh gates on synthetic fixtures generated by the tests (no binary data in git)."""
import math

from character_forge.meshkit import analysis, raster
from character_forge.meshkit.obj import Mesh, read_obj, write_obj
from character_forge.meshkit.skeleton import HUMAN_BONES, build_skeleton, estimate_landmarks, required_landmarks
from character_forge.meshkit.synth import proportions_from_seed, synthetic_humanoid
from character_forge.stages.preflight import compare, silhouettes
from character_forge.util import read_json


def body(**kwargs):
    return synthetic_humanoid(seed=kwargs.pop("seed", 3), **kwargs)


def test_obj_roundtrip_preserves_order_uvs_groups(tmp_path):
    mesh, _ = body()
    path = write_obj(mesh, tmp_path / "m.obj")
    again = read_obj(path)
    assert again.vertices == [tuple(round(c, 6) for c in v) for v in mesh.vertices] or len(again.vertices) == len(mesh.vertices)
    assert again.faces == mesh.faces and again.face_groups == mesh.face_groups
    assert len(again.uvs) == len(mesh.uvs) and again.face_uvs == mesh.face_uvs


def test_clean_body_topology():
    mesh, lm = body()
    topo = analysis.topology_report(mesh)
    assert topo["nonfinite_vertices"] == 0 and topo["degenerate_triangles"] == 0
    assert topo["boundary_edges"] == 0 and topo["nonmanifold_edges"] == 0


def test_debris_is_flagged_not_deleted():
    mesh, lm = body(debris=True)
    # the synthetic body is low-poly, so a fragment is a larger vertex fraction than on a real 30k+ vertex scan
    rows = analysis.component_report(mesh, lm, 1.78, debris_vertex_fraction=0.02)
    debris = [r for r in rows if r["status"] == "debris_candidate"]
    assert len(debris) == 1 and debris[0]["region"] in ("left_upper_arm", "left_shoulder", "torso")
    clean_rows = analysis.component_report(body()[0], lm, 1.78, debris_vertex_fraction=0.02)
    assert not [r for r in clean_rows if r["status"] == "debris_candidate"]
    assert sum(r["vertices"] for r in rows) > sum(r["vertices"] for r in clean_rows)  # nothing removed


def test_uv_seam_duplicates_do_not_split_components():
    mesh, lm = body()
    split = Mesh(list(mesh.vertices), list(mesh.uvs), [], [], [], [])
    # Duplicate every vertex of the first 40 faces (as glTF exporters do at seams) and re-point those faces.
    for index, face in enumerate(mesh.faces):
        if index < 40:
            ids = []
            for v in face:
                split.vertices.append(mesh.vertices[v])
                ids.append(len(split.vertices) - 1)
            face = tuple(ids)
        split.faces.append(face)
        split.face_uvs.append(mesh.face_uvs[index])
        split.face_groups.append(mesh.face_groups[index])
        split.face_materials.append(mesh.face_materials[index])
    assert len(analysis.components(split)) == len(analysis.components(mesh))


def test_completeness_detects_missing_hand():
    mesh, lm = body()
    keep = [i for i, g in enumerate(mesh.face_groups) if not g.startswith("left_") or g in ("left_leg", "left_foot")]
    cut = Mesh(mesh.vertices, mesh.uvs, [mesh.faces[i] for i in keep], [mesh.face_uvs[i] for i in keep],
               [mesh.face_groups[i] for i in keep], [mesh.face_materials[i] for i in keep])
    used = {v for f in cut.faces for v in f}
    cut.vertices = [v if i in used else (0.0, 0.0, -50.0) for i, v in enumerate(cut.vertices)]
    report = analysis.completeness_report(cut, lm, 1.78)
    assert report["left_fingertips"] == 0 and report["left_wrist"] == 0
    assert report["right_fingertips"] > 0 and report["head_top"] > 0


def test_digit_separation_detects_fused_fingers():
    mesh, lm = body()
    neighbours = analysis.adjacency(mesh, analysis.weld_map(mesh.vertices))
    ok = analysis.digit_separation(mesh.vertices, neighbours, lm["LeftHand"], lm["LeftMiddleTip"])
    assert ok["distal_digit_sections"] == 4
    fused, lm2 = body(fused_fingers=True)
    neighbours = analysis.adjacency(fused, analysis.weld_map(fused.vertices))
    bad = analysis.digit_separation(fused.vertices, neighbours, lm2["LeftHand"], lm2["LeftMiddleTip"])
    assert bad["distal_digit_sections"] <= 1


def test_face_uv_density_and_subpixel_triangles():
    mesh, lm = body()
    good = analysis.uv_report(mesh, lm, 2048)
    assert good["faces_missing_uv"] == 0 and good["subpixel_triangles_head"] == 0
    assert good["head_to_body_density_ratio"] > 1.2
    tiny, lm2 = body(tiny_head_uv=True)
    bad = analysis.uv_report(tiny, lm2, 2048)
    assert bad["subpixel_triangles_head"] > 0 or bad["head_to_body_density_ratio"] < 0.5
    assert bad["head_to_body_density_ratio"] < good["head_to_body_density_ratio"]


def test_degenerate_and_nonfinite_detection():
    mesh = Mesh(vertices=[(0, 0, 0), (1, 0, 0), (2, 0, 0), (0, 1, 0), (float("nan"), 0, 0)],
                faces=[(0, 1, 2), (0, 1, 3), (1, 0, 3)], face_uvs=[None] * 3, face_groups=["a"] * 3, face_materials=["m"] * 3)
    topo = analysis.topology_report(mesh)
    assert topo["degenerate_triangles"] == 1 and topo["nonfinite_vertices"] == 1
    mesh.faces.append((0, 1, 3))  # third face on edge 0-1 -> non-manifold
    mesh.face_uvs.append(None); mesh.face_groups.append("a"); mesh.face_materials.append("m")
    assert analysis.topology_report(mesh)["nonmanifold_edges"] >= 1


def test_landmark_estimate_is_close_on_synthetic_body():
    mesh, truth = body(seed=11)
    estimate = estimate_landmarks(mesh.vertices)
    assert set(required_landmarks()) <= set(estimate)
    h = max(v[2] for v in mesh.vertices)
    for name in ("Hips", "LeftHand", "RightHand", "LeftLowerArm", "LeftLowerLeg", "LeftFoot", "Head"):
        assert math.dist(estimate[name], truth[name]) < 0.05 * h, name
    skeleton = build_skeleton(estimate)
    assert set(HUMAN_BONES) <= set(skeleton.bones)


def test_individuality_flags_clones_and_passes_distinct_bodies():
    a = silhouettes(body(seed=1)[0])
    clone = silhouettes(body(seed=1)[0])
    other = silhouettes(synthetic_humanoid(proportions_from_seed(77))[0])
    rows = compare(a, [("clone", {"views": clone}), ("other", {"views": other})])
    assert rows[0]["character"] == "clone" and rows[0]["mean_iou"] > 0.99
    assert rows[1]["mean_iou"] < rows[0]["mean_iou"]


def test_individuality_gate_end_to_end(forge):
    forge("new", "orig", "--brief", "zombie", "--mode", "fake", "--seed", "5")
    forge("new", "copy", "--brief", "zombie", "--mode", "fake", "--seed", "5")
    forge.approve_all_and_run("orig")
    forge("run", "copy")
    forge("approve", "copy", "--stage", "reference", "--by", "human", "--note", "ok")
    code, out = forge("run", "copy")
    assert code == 1 and "individuality_not_duplicate" in out
    forge("new", "fresh", "--brief", "zombie", "--mode", "fake", "--seed", "4242")
    forge("run", "fresh")
    forge("approve", "fresh", "--stage", "reference", "--by", "human", "--note", "ok")
    code, out = forge("run", "fresh")
    assert code == 3  # awaiting approval at preflight, not failed
    gate = read_json(next((forge.ws("fresh").stage_dir("preflight") / "runs").iterdir()) / "gate.json")
    nearest = gate["metrics"]["individuality_nearest"]
    assert {r["character"] for r in nearest} == {"orig", "copy"}


def test_rle_roundtrip_and_iou():
    mesh, _ = body()
    tris = [t for _, t, _ in mesh.triangles()]
    _, _, _, mask = raster.render(mesh.vertices, tris, "front", 64, shade=False)
    assert raster.rle_to_mask(raster.mask_to_rle(mask)) == mask
    assert raster.iou(mask, mask) == 1.0
    assert sum(map(sum, mask)) > 100
